mapper.select:
SELECT S.SYMBOL ,S.NAME ,D.TITLE ,D.CONTENT FROM T_STOCK_DOC D JOIN T_STOCK S ON S.ID = D.STOCK_ID WHERE 1=1 AND D.DEL_DAY IS NULL AND (
D.TITLE ILIKE '%' || #{kw} || '%' OR D.CONTENT ILIKE '%' || #{kw} || '%' OR S.NAME ILIKE '%' || #{kw} || '%'
) ORDER BY D.ID LIMIT 5

mapper.update:
UPDATE T_AI_CHAT_LOG
SET  RATING       = #{rating}
,FEEDBACK_DAY = NOW()
WHERE 1=1
AND ID      = #{chatId}
AND USER_ID = #{userId}

mapper.select:
WITH RANKED AS ( SELECT P.STOCK_ID ,P.TRADE_DATE ,P.CLOSE_PRICE ,P.VOLUME ,ROW_NUMBER() OVER (PARTITION BY P.STOCK_ID ORDER BY P.TRADE_DATE DESC) AS RN ,P.CLOSE_PRICE - LEAD(P.CLOSE_PRICE) OVER (PARTITION BY P.STOCK_ID ORDER BY P.TRADE_DATE DESC) AS DIFF FROM T_STOCK_PRICE P WHERE 1=1 AND P.TRADE_DATE >= CURRENT_DATE - (GREATEST(#{days}, 21) * 2 + 14) ), AGG AS ( SELECT R.STOCK_ID ,MAX(CASE WHEN R.RN = 1 THEN R.TRADE_DATE END) AS END_DATE ,MAX(CASE WHEN R.RN = 1 THEN R.CLOSE_PRICE END) AS END_PRICE ,MAX(CASE WHEN R.RN = 2 THEN R.CLOSE_PRICE END) AS PREV_PRICE ,MAX(CASE WHEN R.RN = #{days} + 1 THEN R.TRADE_DATE END) AS START_DATE ,MAX(CASE WHEN R.RN = #{days} + 1 THEN R.CLOSE_PRICE END) AS START_PRICE ,MAX(CASE WHEN R.RN = 1 THEN R.VOLUME END) AS LAST_VOLUME ,AVG(CASE WHEN R.RN BETWEEN 2 AND #{days} + 1 THEN R.VOLUME END) AS AVG_VOLUME ,MAX(CASE WHEN R.RN <= #{days} + 1 THEN R.CLOSE_PRICE END) AS PERIOD_HIGH ,COALESCE(MIN(CASE WHEN R.DIFF IS NULL OR R.DIFF <= 0 THEN R.RN END), MAX(R.RN) + 1) - 1 AS UP_STREAK ,COALESCE(MIN(CASE WHEN R.DIFF IS NULL OR R.DIFF >= 0 THEN R.RN END), MAX(R.RN) + 1) - 1 AS DOWN_STREAK FROM RANKED R WHERE 1=1 AND R.RN <= GREATEST(#{days} + 1, 21) GROUP BY R.STOCK_ID ), BASE AS ( SELECT MODE() WITHIN GROUP (ORDER BY A.END_DATE) AS BASE_DATE FROM AGG A ), RESULT AS ( SELECT S.SYMBOL ,S.NAME ,S.MARKET AS STOCK_MARKET ,S.SECURITY_TYPE ,A.START_DATE ,A.END_DATE ,A.END_PRICE AS CLOSE_PRICE ,ROUND((A.END_PRICE - A.START_PRICE) / NULLIF(A.START_PRICE, 0) * 100, 2) AS RETURN_RATE ,ROUND((A.END_PRICE - A.PREV_PRICE) / NULLIF(A.PREV_PRICE, 0) * 100, 2) AS CHANGE_RATE ,ROUND(A.END_PRICE * S.SHARES_OUTSTANDING / 100000000) AS MARKET_CAP_EOK ,A.UP_STREAK ,A.DOWN_STREAK ,ROUND(A.LAST_VOLUME / NULLIF(A.AVG_VOLUME, 0), 2) AS VOLUME_RATIO ,ROUND((A.END_PRICE - A.PERIOD_HIGH) / NULLIF(A.PERIOD_HIGH, 0) * 100, 2) AS FROM_HIGH FROM AGG A JOIN T_STOCK S ON S.ID = A.STOCK_ID CROSS JOIN BASE B WHERE 1=1 AND S.USE_YN = 'Y' AND S.DEL_DAY IS NULL AND A.END_DATE >= B.BASE_DATE AND A.START_PRICE IS NOT NULL
AND S.SECURITY_TYPE = 'STOCK' AND S.MARKET = #{market}
AND S.SECURITY_TYPE = 'ETF'
AND S.SECURITY_TYPE = 'STOCK'
) SELECT X.* ,COUNT(*) OVER () AS MATCH_COUNT FROM RESULT X WHERE 1=1 AND X.RETURN_RATE >= #{minReturn} AND X.RETURN_RATE <= #{maxReturn} AND X.CHANGE_RATE >= #{minChange} AND X.CHANGE_RATE <= #{maxChange} AND X.MARKET_CAP_EOK >= #{minCapEok} AND X.MARKET_CAP_EOK <= #{maxCapEok} AND X.CLOSE_PRICE >= #{minPrice} AND X.CLOSE_PRICE <= #{maxPrice} AND X.UP_STREAK >= #{minUpStreak} AND X.DOWN_STREAK >= #{minDownStreak} AND X.VOLUME_RATIO >= #{minVolumeRatio} AND X.FROM_HIGH >= 0 - #{maxFromHigh} ORDER BY
X.RETURN_RATE ASC X.CHANGE_RATE DESC X.CHANGE_RATE ASC X.MARKET_CAP_EOK DESC NULLS LAST X.VOLUME_RATIO DESC NULLS LAST X.UP_STREAK DESC, X.RETURN_RATE DESC X.DOWN_STREAK DESC, X.RETURN_RATE ASC X.RETURN_RATE DESC
,X.SYMBOL LIMIT #{limit}

SELECT X.TITLE ,X.PRESS ,X.LINK ,X.PUB_DATE ,X.NAME FROM ( SELECT DISTINCT ON (N.TITLE) N.TITLE ,N.PRESS ,N.LINK ,N.PUB_DATE ,S.NAME FROM T_NEWS N LEFT JOIN T_STOCK S ON S.ID = N.STOCK_ID WHERE 1=1 AND N.PUB_DATE >= NOW() - (#{days} || ' days')::INTERVAL AND (
N.TITLE ILIKE '%' || #{kw} || '%' OR S.NAME ILIKE '%' || #{kw} || '%'
) ORDER BY N.TITLE ,N.PUB_DATE DESC ) X ORDER BY X.PUB_DATE DESC LIMIT 10
